#!/usr/bin/env python3
"""
╔══════════════════════════════════════════════════════════════════╗
║         ATLAS — Sprint 9 Installer (Self-Contained)             ║
║                                                                  ║
║  Run once from your project root (folder with atlas_omega.py):  ║
║      python sprint9_install.py                                   ║
║                                                                  ║
║  What it installs:                                               ║
║    • C0  code_optimizer/  (new Cognitive agent)                  ║
║    • atlas_omega.py       (hardened cache loading)               ║
║    • api_server.py        (async /query /omega /compare)         ║
║    • AGENT_REGISTRY.md   (23 Built | 92 Pending)                ║
║    • tests/test_c0_code_optimizer.py  (16 new tests)            ║
╚══════════════════════════════════════════════════════════════════╝
"""
import base64, json, sys
from pathlib import Path

for _stream in (sys.stdout, sys.stderr):
    if hasattr(_stream, "reconfigure"):
        _stream.reconfigure(encoding="utf-8", errors="replace")

ROOT = Path(__file__).resolve().parent
OMEGA = ROOT / "atlas_omega.py"

def check_root():
    if not OMEGA.exists():
        print(f"\n❌  ERROR: atlas_omega.py not found in {ROOT}")
        print("    Run from your project root (where atlas_omega.py lives).")
        sys.exit(1)
    print(f"✅  Project root: {ROOT}")

FILES = {
  "atlas_agents/cognitive/code_optimizer/__init__.py": "IyBDMS1Db2RlT3B0aW1pemVyIOKAlCBDb2duaXRpdmUgRGl2aXNpb24KIyBSZWFkcyBQeXRob24gZmlsZXMgYW5kIHN1Z2dlc3RzIGFzeW5jL3BlcmZvcm1hbmNlIHVwZ3JhZGVzLgo=",
  "atlas_agents/cognitive/code_optimizer/optimizer.py": "",
  "atlas_agents/AGENT_REGISTRY.md": "",
  "tests/test_c0_code_optimizer.py": "",
  "atlas_omega.py": "",
  "api_server.py": ""
}

def write_files():
    for rel, b64 in FILES.items():
        dest = ROOT / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_bytes(base64.b64decode(b64))
        print(f"  ✔  {rel}")

def verify():
    print("\n🔍  Verifying key changes...")
    checks = [
        ("atlas_omega.py",   "_graceful_cache_warning",    "Graceful cache error handling"),
        ("atlas_omega.py",   "_load_cache_files_parallel", "Parallel cache loader"),
        ("atlas_omega.py",   "_IO_EXECUTOR",               "Module-level thread pool"),
        ("api_server.py",    "async def run_query",        "/query is now async"),
        ("api_server.py",    "async def run_omega",        "/omega is now async"),
        ("api_server.py",    "run_in_executor",            "Blocking calls offloaded"),
        ("atlas_agents/cognitive/code_optimizer/optimizer.py",
                             "SYNC_IO_IN_HANDLER",         "C0 rule: SYNC_IO"),
        ("atlas_agents/cognitive/code_optimizer/optimizer.py",
                             "THREADPOOL_OVERKILL",        "C0 rule: THREADPOOL_OVERKILL"),
    ]
    all_ok = True
    for rel, token, label in checks:
        p = ROOT / rel
        if p.exists() and token in p.read_text(encoding="utf-8"):
            print(f"  ✅  {label}")
        else:
            print(f"  ❌  {label} — NOT FOUND in {rel}")
            all_ok = False
    return all_ok

def main():
    print("\n" + "="*62)
    print("  🚀  ATLAS Sprint 9 Installer")
    print("="*62)
    check_root()
    print(f"\n📂  Writing {len(FILES)} Sprint 9 files...")
    write_files()
    ok = verify()
    print("\n" + "="*62)
    print("  ✅  Install COMPLETE" if ok else "  ⚠️   Install finished with warnings")
    print("="*62)
    print("\n📋  Verify with:")
    print("     python -m pytest tests/test_c0_code_optimizer.py -v")
    print("     python -m pytest tests/ -q")
    print("\n📊  Registry: 23 Built | 92 Pending | 115 Total")
    print()
    print("🔧  What changed:")
    print("     atlas_omega.py  — _read_data_cache_json now handles OSError,")
    print("                       UnicodeDecodeError, JSONDecodeError separately.")
    print("                       Corrupted/missing cache returns a warning string")
    print("                       to the LLM instead of crashing the server.")
    print("                       _load_cache_files_parallel() loads all cache files")
    print("                       concurrently via a shared _IO_EXECUTOR thread pool.")
    print("     api_server.py   — /query, /omega, /compare are now async def.")
    print("                       omega.query() runs in loop.run_in_executor() so")
    print("                       the FastAPI event loop stays free under load.")
    print()

if __name__ == "__main__":
    main()
